sys_script_include.script:
var AccessGovernanceUtils = Class.create();
AccessGovernanceUtils.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    /**
     * Check if the user already has an active access record for the requested application
     * Called asynchronously from Client Scripts via GlideAjax
     */
    checkActiveAccess: function() {
        var userId = this.getParameter('sysparm_user_id');
        var appId = this.getParameter('sysparm_app_id');

        if (!userId || !appId) {
            return false;
        }

        var accessGr = new GlideRecord('x_2098628_ds_ent_0_access_inventory');
        accessGr.addQuery('user', userId);
        accessGr.addQuery('application', appId);
        accessGr.addQuery('state', 'active');
        accessGr.query();

        return accessGr.hasNext();
    },

    type: 'AccessGovernanceUtils'
});
